SET session_replication_role = 'replica';
insert into public.chunks (id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length)
select id, episode_id, cms_item_id, chunk_index, content, token_estimate, speakers, start_timestamp, end_timestamp, podcast_index, episode_name, slug, web_url, guest_name, guest_title, categories, short_description, podcast_length
from jsonb_to_recordset($jsonpayload$
[{"id": "a234b41f-9c06-4769-9018-62f9b29c3f04", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 9, "content": "Cole Heilborn (22:53): Can you share more about how you justify the ROI And I think what's cool is you guys, and this is coming from your mouth, you're a relatively small brand, but you've figured out a way to really make something that punches above your own weight class, which is pretty awesome. Can you share, you're going into season three, obviously season two was worth it. How was it worth it? Why was it worth it?\n\nChris Pew (23:19): So there's so many different ways to measure ROI in general, but in this project we looked at, there's the kind of tactical ROI, we can see every person that votes you vote with an email. And so we can just watch this cohort of emails that become customers and we can watch that revenue grow over time. And so the first season, and we can share numbers because your audience would find interesting, a bunch of industry marketing people. First season, I think we captured under 4,000 total emails and that first season's cohort over the past 18 months, I guess that they were customers, lemme think about that. Or 12 months that they were customers have spent $18,000 at TREW. And so that's their lifetime value to date that they'll just, one thing, to your point about us being a small company, one thing that we do really well is we sell a lot of products to a small amount of people. So there's a 50% chance you're going to come back and buy something else if you've bought anything from TREW. And we are able to keep growing that relationship with our small amount of customers. So that number may not feel very big for a lot of bigger brands, but for us, that's a big slice of the pie. So out of those 4,000 emails, a few hundred become customers over the last\n\nCole Heilborn (24:55): 12 months that you've", "token_estimate": 439, "speakers": ["Cole Heilborn", "Chris Pew"], "start_timestamp": "22:53", "end_timestamp": "24:55", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}, {"id": "16d40803-4ecb-4e17-9374-8af56f34f57f", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 10, "content": "Chris Pew (24:55): Seen over 12 months. Yeah, exactly. Some buy something right away, they vote and they get put in a funnel and they get welcome to TREW or whatever, and some buy something right away and some buy something six months later, some make multiple purchases. But we can just basically take our entire list of customers and just look at, okay, this is how much revenue we've done in this amount of time. Let's zero in on this cohort of TREW to you voters and let's filter for that cohort and see what their activities like. And right away, that's the first ROI metric that we look at to be like, that's the first question when you talk about how do we differentiate ourselves? And I kept saying, yeah, we want to differentiate ourselves. We want to find our customer. This is a great design to find our customer. If you are interested in this project, you're maybe a connected one of the teams that participate in it, or you're just really interested in this kind of niche skiing, snowboarding content, you're probably going to be pretty interested in our products. (26:03): So you're already filtering yourself down into this pool of interested people. And that's just a different way of taking all of meta or whatever, everyone who's online and being like, have you ever liked an outdoor company or a ski film company or something like that. We don't have a lot of luck going for these huge kind of awareness campaigns. We have a lot more luck and we're a lot more efficient when we're more targeted. So that's really what this is, is it's like a way to filter in a new list of customers. And then just to give you an idea of how it's grown, season two, we got almost eight or just over 8,000 emails, so almost double the size the email list, only a small amount have become customers yet because we literally just onboarded the voting closed right after Thanksgiving, so just less than two weeks ago. (26:58): And so the next stage is let's look at how that segment of customers season one, season two, and how does that grow over time and what's the crossover between those two things? And so that's where it becomes really interesting from just a marketing metric, ROI. And then the other piece that I don't think we'd be doing this project if we didn't have it was the in-person event piece. And that's where you just go out and it's like more traditional grassroots, scrappy marketing where you're just talking with new and existing customers and that is a tremendous value. Or the teams that have participated are telling you, thank you so much for this platform. We had this idea for a ski film that we wanted to do forever, and we just never had the reason to scrap it all to bring it all together. So just hearing that I put that in an ROI category, I don't know what the metric is, but it's like in-person community, goodwill, going out, talking to people, we bring samples, we show people product. That's a pretty small amount of what those in-person events are all about. They're more about establishing relationships and just, it's the old school ski film style where you come to a place and you just talk to people about skiing, which is what skis and snowboarders like to do if they're not skiing or snowboarding. So that's I guess the second bucket. (28:32): And then the last bucket of ROI is like, what is the reach? So how can we get this thing digitally or on trade publications or something like that to have a reach a wider audience? And I'd say that's probably the bucket that has been leased, capitalized by us. We are a small enough company. We actually don't have a PR agency of record right now, so we just put out our own press releases. We kind of put these things on YouTube, but we haven't really optimized them yet for YouTube. So I'd say this project really lives in our channels, in our own channels, email and the channels of our partners. And then it lives in person. And I think the next evolution is like, okay, well how do we give this thing a really robust and long lasting meaningful digital life? Just kind of interesting. I feel like it's flipped from a lot of times companies are like, let's make the viral video. And we designed this project to be like, let's get everything we want to value before ever thinking about whether or not this would be a viral video or something. The whole value of it is in the creation, in the application, in the tour, in the engagement of our community, in the voting, all of that is the kind of soul this project. And then maybe the next steps are like, okay, how do we let it grow on its own a little bit?", "token_estimate": 1150, "speakers": ["Chris Pew"], "start_timestamp": "24:55", "end_timestamp": "24:55", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}, {"id": "5dd31887-3265-4c07-b466-046d9db5d5c0", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 11, "content": "Cole Heilborn (30:04): Yeah. So you mentioned three points of ROI to recap emails, the value of just being in person and community building together in person, and then the reach, maybe a fourth one would be the actual content itself. As part of all this, you guys get content to be used in a variety of different ways.\n\nChris Pew (30:24): Yeah, that's right. Yeah, we get photos, we get photography and we get videos. A lot of parts. This project, I feel like we haven't even totally realized the value of this stuff yet. Now we're just sitting on a treasure trove of really cool user generated content, but that is definitely a big return or value driver for this project.\n\nCole Heilborn (30:52): One idea I just had was like, could you do, so you've got all these filmmakers telling these stories, right? 10 filmmakers telling 10 stories or 10 teams rather. Could you do an interview series with each of the filmmakers once their story has been published and you could go deep into why'd you want to make this? How did this idea come to be? And you could create, it could be an interview, it could be a podcast, it could be its own YouTube series. There could be something to dig in a little deeper there.", "token_estimate": 302, "speakers": ["Cole Heilborn", "Chris Pew"], "start_timestamp": "30:04", "end_timestamp": "30:52", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}, {"id": "3a5d98a7-7fbb-4f5c-9d8d-ec82ef38b3d2", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 12, "content": "Chris Pew (31:20): Yeah, I love that. That's a great segue actually to, we can talk about the changes we're making to season three. Myself and Jess who manages this project on our team, when we sat down and talked about the opportunities with this project, maybe what's missing? How do we improve it? That was a huge part of it is we want to go deeper with each team and with 10 teams in such a short window. It was basically it's felt like we were moving heaven and earth just to get the files from these teams and help them along the way. And so next season or this season that we're accepting applications for, we're going to pick five teams. So we're going to cut down the total amount of films in half and we're going to have them make a slightly longer film. So it'll be a seven minute cap. (32:13): And then we're also hiring an executive producer, so a really experienced filmmaker and editor. They'll have some backend knowledge of technical stuff, color correction, audio, stuff like that, exports, but also have some feedback for the process. We're going to design check-ins. So like, Hey, let's look at the storyboard. Well, first of all, here's a template for storyboard that our panel of experts in this EP have put together. Here's the resources, here's something you can read or a YouTube video or whatever. Just like if you need it, let's dive in and we want to give you these resources. If you're experienced filmmaker, no problem, you've probably done this before, but we're going to establish check-ins along the way. Show us some of the selects. Show us your first edit, and we'll be in touch for any problems if they've run into licensing music problems, which has been a struggle in the past or any type of teams, having that short of a window, especially for teams that have never put a film together before they run into all sorts of stuff. (33:30): Oh, we had a filmer that then he got called on different project, so we had to scrap something together and we want to be a part of the process, much more a part of the process this season than we have in the past in order to be a resource and help these teams create truly the vision that they've had. And in that sense, it kind of takes on this other component as an incubator. So now it's like we're lifting up, we're helping people, we're pushing them into the next phase of their creative career in skiing and snowboarding. And so as we do that, to get back to your original prompt or question, it's like, yes, we'll establish a closer relationship with these teams, build some behind the scenes footage. (34:21): And also the way we're structuring it this season and next season is the winning team, instead of just getting a cash prize and everyone goes on their separate ways, our cash prize will fund the feature length film for next year's tour. So in 2020, like this year coming up, we're going to feature a production of a film that we're supporting from a TREW to you alumni. That's a 10 minute film that we're going to help produce. And then you'll watch five of the contest films, and then the winning film will be chosen by combination of popular vote and a judges panel that we're putting together. So we're bringing in a little bit more of that film festival type of vibe. Instead of pure popular vote, we're going to start judging the films on creativity, storytelling, execution. And then the winning film will get to pick the theme for next year, and there'll be the feature presentation that we're going to produce their film. (35:17): So it becomes this cycle of we're going to help them make the film in the contest and whoever wins, we're going to help them with even bigger budget, produce a bigger, more impactful film. So yeah, that's season three and you can already tell where we're going. We've gone pure user generated kind of like, Hey, help fill in the blank what our brand's all about. And now just after two seasons, we've kind of arrived at this like, oh, this is more about uplifting filmers and storytellers and finding these new really valuable, interesting stories that are waiting to be told and skiing and snowboarding that needs to be highlighted and different perspectives and point of views.", "token_estimate": 1053, "speakers": ["Chris Pew"], "start_timestamp": "31:20", "end_timestamp": "31:20", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}, {"id": "8d2a0884-2651-47a0-ae15-d7a4aec915a3", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 13, "content": "Cole Heilborn (36:07): Yeah, (36:07): I mean, I'm sitting here getting excited for you guys, it seems like you're on the ground floor of, or maybe your three floors up of something that could be pretty incredible because I feel like what you're doing is the stuff that I love. It's like how do you take the real world marketing objectives and business needs and how do you couple that with creativity and stories and film, and you guys have come up with a really neat way to bring those worlds together that's working that maybe it doesn't require a huge internal team or a giant agency to help you produce it. It's something that you guys can do and it's working at its barest minimalist point. It's working, so it can only work better from here on out. Right.\n\nChris Pew (36:51): Yeah, I appreciate that, Cole. And I mean, I think that's the value of ideas like this for small companies like us is it has to work, but it also has to be something that we're pretty motivated to do. I agree with you. It's an exciting prospect. It does feel like we're definitely on the ground floor or something, and we'll talk again next year though, where the next evolution might lead. It already changed and morphed a lot in the past two years.\n\nCole Heilborn (37:22): Chris, anything we haven't talked about that you want to leave with folks? Any last thoughts? Again, I think you guys are doing an awesome job. It's awesome to hear the creativity and how you guys are standing out and making an impact while doing it.", "token_estimate": 377, "speakers": ["Cole Heilborn", "Chris Pew"], "start_timestamp": "36:07", "end_timestamp": "37:22", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}, {"id": "d2680832-34fa-4747-887d-b400e87ae117", "episode_id": "8fe50214-e3d5-42f0-a033-e0336f5f08fb", "cms_item_id": "68225dfc7bb476527f8c4961", "chunk_index": 14, "content": "Chris Pew (37:37): Yeah. Thanks Cole. I appreciate it. I mean, I think we talked about, I'm just excited to be able to talk about this project and I think we covered it pretty extensively. And yeah, no, I love the discussion and thanks for having me on the show. I love the conversations you've had. It's like I've learned a lot from a lot of the other conversations. And a lot of it's in this same vein of subject matter we're talking about. It's like this nuanced look at ROI, right? There's some podcasts that are like, how do you get rich quick vlogging, ROI? And you're like, that's stressful for me. That's kind of Gary V type stuff is like, that's not what we're doing here. And so I appreciate your perspective on stuff. There's like, yeah, you ask ROI questions, but there's also in our industry, ROI is like how did that feel for community?\n\nCole Heilborn (38:36): Sometimes ROI is just a high five and a good beer shared\n\nChris Pew (38:41): With someone else. That's well put. Yeah,\n\nCole Heilborn (38:44): Right on, Chris. Well thanks again. If they want to learn more about the film series, if folks want to apply, if they want to stay tuned for season three, where can they go to learn more?\n\nChris Pew (38:55): Yeah, I mean, our website has its own section of the dropdown menu that has information about the TREW to You tour, but certainly subscribing to our email or following along on our channels is where we're constantly updating people about this contest. But yeah, just subscribe to us and we'll tell you about it.\n\nCole Heilborn (39:20): Right on. Alright, Chris, well have a great rest of your day. I hope you get up to the hill and get some turns in here.\n\nChris Pew (39:27): Yeah, thanks Cole. You too. ‍", "token_estimate": 433, "speakers": ["Chris Pew", "Cole Heilborn"], "start_timestamp": "37:37", "end_timestamp": "39:27", "podcast_index": 195, "episode_name": "TREW Gear - Creating a Branded Film Festival", "slug": "trew-gear---creating-a-branded-film-festival", "web_url": "https://www.portsidepro.com/podcast-feed/trew-gear---creating-a-branded-film-festival", "guest_name": "Chris Pew", "guest_title": "Ceo and Co-Founder of TREW Gear", "categories": ["creative", "brand"], "short_description": "Chris shares how TREW is fostering deeper connections with its core audience through storytelling and innovative community engagement strategies. The conversation spans the evolution of ski film culture, the role of social media in building authentic communities, and how small brands can leverage creativity to make a big impact.", "podcast_length": "39:29"}]
$jsonpayload$::jsonb) as t(id uuid, episode_id uuid, cms_item_id text, chunk_index integer, content text, token_estimate integer, speakers text[], start_timestamp text, end_timestamp text, podcast_index integer, episode_name text, slug text, web_url text, guest_name text, guest_title text, categories text[], short_description text, podcast_length text)
on conflict (id) do update set
  episode_id = excluded.episode_id, cms_item_id = excluded.cms_item_id, chunk_index = excluded.chunk_index, content = excluded.content, token_estimate = excluded.token_estimate, speakers = excluded.speakers, start_timestamp = excluded.start_timestamp, end_timestamp = excluded.end_timestamp, podcast_index = excluded.podcast_index, episode_name = excluded.episode_name, slug = excluded.slug, web_url = excluded.web_url, guest_name = excluded.guest_name, guest_title = excluded.guest_title, categories = excluded.categories, short_description = excluded.short_description, podcast_length = excluded.podcast_length;
